import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Profession System","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/professions/overview.md","filePath":"en/guide/professions/overview.md"}'),s={name:"en/guide/professions/overview.md"};function n(o,e,l,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="profession-system" tabindex="-1">Profession System <a class="header-anchor" href="#profession-system" aria-label="Permalink to &quot;Profession System&quot;">​</a></h1><p><strong>Status:</strong> Proposed · Not established as playable.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>A profession belongs to your adventuring character, within the shared <a href="/Syrolands-Public/en/guide/characters/skills.html">skill</a> budget.</li><li>Learn processes and <a href="/Syrolands-Public/en/guide/characters/techniques.html">techniques</a>; practice execution and build a reputation.</li><li>Useful early work, discovery and commissions should matter beyond reaching maximum skill.</li></ul><p><span id="professions-in-syrolands"></span><span id="at-a-glance"></span><span id="crafts-belong-to-adventurers"></span><span id="learning-and-becoming-known"></span><span id="knowledge-and-production"></span><span id="shared-character-rules"></span><span id="inscription-and-magical-knowledge"></span></p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Activity</th><th>What you do</th></tr></thead><tbody><tr><td>Skill</td><td>Broad capability and <a href="/Syrolands-Public/en/guide/glossary.html#consistency">consistency</a> within the same character budget as other skills.</td></tr><tr><td>Technique</td><td>Learned methods such as Distillation or Bowmaking; not automatic rewards for skill totals.</td></tr><tr><td><a href="/Syrolands-Public/en/guide/glossary.html#profession-path">Profession Path</a></td><td>Combine skills, techniques and practice into a specialization.</td></tr><tr><td>Knowledge and identity</td><td>Journals record discoveries; actual products and commissions build reputation.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Compared with classic UO <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Permalink to &quot;Compared with classic UO&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic UO</th><th>Syrolands direction</th></tr></thead><tbody><tr><td>Craft skills already share a character’s skill budget.</td><td>Field, survival and exploration roles encourage taking a craft on adventures.</td></tr><tr><td>Tools, materials and skill checks drive familiar crafting loops.</td><td>Interactive processes, learned knowledge and execution shape results.</td></tr><tr><td>Later UO includes recipe learning and Bulk Order Deeds.</td><td>Discovery and functional commissions emphasize fitness for purpose and reputation.</td></tr></tbody></table><p>Comparison uses familiar UO crafting loops; the official references also cover later expansions. <a href="https://uo.com/wiki/ultima-online-wiki/skills/blacksmithing/" target="_blank" rel="noreferrer">Blacksmithing</a> · <a href="https://uo.com/wiki/ultima-online-wiki/skills/tailoring/" target="_blank" rel="noreferrer">Tailoring</a>.</p><h2 id="explore-the-professions" tabindex="-1">Explore the professions <a class="header-anchor" href="#explore-the-professions" aria-label="Permalink to &quot;Explore the professions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Profession</th><th>Role</th></tr></thead><tbody><tr><td><a href="/Syrolands-Public/en/guide/professions/cooking.html">Cooking</a></td><td>Food and survival</td></tr><tr><td><a href="/Syrolands-Public/en/guide/professions/alchemy.html">Alchemy</a></td><td>Reactions and preparations</td></tr><tr><td><a href="/Syrolands-Public/en/guide/professions/mining.html">Mining</a></td><td>Geology and extraction</td></tr><tr><td><a href="/Syrolands-Public/en/guide/professions/blacksmithing.html">Blacksmithing</a></td><td>Metal and maintenance</td></tr><tr><td><a href="/Syrolands-Public/en/guide/professions/tailoring.html">Tailoring</a></td><td>Flexible protection and fashion</td></tr><tr><td><a href="/Syrolands-Public/en/guide/professions/lumberjacking.html">Lumberjacking</a></td><td>Timber and felling</td></tr><tr><td><a href="/Syrolands-Public/en/guide/professions/carpentry.html">Carpentry</a></td><td>Woodwork and learned Bowmaking</td></tr><tr><td><a href="/Syrolands-Public/en/guide/professions/tinkering.html">Tinkering</a></td><td>Mechanisms and security</td></tr><tr><td><a href="/Syrolands-Public/en/guide/professions/inscription.html">Inscription</a></td><td>Magical notation and references</td></tr></tbody></table><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>An explorer with Blacksmithing could maintain equipment and become known for dependable field weapons, without becoming a workshop-only character.</p><h2 id="progression-and-trade-offs" tabindex="-1">Progression and trade-offs <a class="header-anchor" href="#progression-and-trade-offs" aria-label="Permalink to &quot;Progression and trade-offs&quot;">​</a></h2><ul><li>The current direction is roughly 700 total skill points and 100 normally per skill. Useful characters need not maximize seven skills.</li><li>Manual discovery establishes <a href="/Syrolands-Public/en/guide/glossary.html#mastery">mastery</a>; known work may be repeated in station batches using real time and materials. Movement, combat or station loss can interrupt production.</li><li>Knowledge can be shared, but execution cannot be copied. Production thresholds, teaching and commission rules remain open.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/characters/skills.html">Skills and progression</a> · <a href="/Syrolands-Public/en/guide/characters/techniques.html">Techniques</a> · <a href="/Syrolands-Public/en/guide/items/item-quality.html">Item Quality</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/professions/profession-system.html">Profession System</a></p>',20)])])}const m=a(s,[["render",n]]);export{p as __pageData,m as default};
